-- Worksheets.
ALTER TABLE "construction_site_work"."worksheets" ADD CONSTRAINT "worksheets_counts_check" CHECK (
  ("skilled_count" IS NULL OR "skilled_count" >= 0)
  AND ("unskilled_count" IS NULL OR "unskilled_count" >= 0)
  AND ("approx_work_qty" IS NULL OR ("approx_work_qty" > 0 AND "approx_work_unit_id" IS NOT NULL))
);
ALTER TABLE "construction_site_work"."worksheets" ADD CONSTRAINT "worksheets_rejection_check" CHECK ("approval_status" <> 'rejected' OR "rejection_reason" IS NOT NULL);
ALTER TABLE "construction_site_work"."worksheet_materials" ADD CONSTRAINT "worksheet_materials_quantity_check" CHECK ("quantity" > 0);

-- Equipment.
ALTER TABLE "construction_site_work"."equipment" ADD CONSTRAINT "equipment_hire_check" CHECK (
  ("ownership" = 'rented' AND "hire_party_id" IS NOT NULL AND "hire_basis" IS NOT NULL AND "hire_rate" IS NOT NULL AND "hire_rate" >= 0)
  OR ("ownership" = 'owned' AND "hire_party_id" IS NULL AND "hire_basis" IS NULL AND "hire_rate" IS NULL)
);
ALTER TABLE "construction_site_work"."equipment" ADD CONSTRAINT "equipment_figures_check" CHECK (
  ("purchase_year" IS NULL OR "purchase_year" BETWEEN 1950 AND 2100)
  AND ("target_value" IS NULL OR ("target_value" > 0 AND "target_unit" IS NOT NULL))
  AND ("min_utilisation_pct" IS NULL OR "min_utilisation_pct" BETWEEN 0 AND 100)
  AND ("expected_fuel_efficiency" IS NULL OR "expected_fuel_efficiency" > 0)
  AND ("working_time_method" <> 'both' OR "utilisation_basis" = 'hourly')
  AND ("available_for_entry" OR "unavailable_since" IS NOT NULL)
);
ALTER TABLE "construction_site_work"."equipment_movements" ADD CONSTRAINT "equipment_movements_route_check" CHECK (
  ("kind" = 'to_warehouse' AND "to_project_id" IS NULL)
  OR ("kind" = 'to_project' AND "to_project_id" IS NOT NULL AND "to_project_id" IS DISTINCT FROM "from_project_id")
  OR ("kind" = 'added' AND "from_project_id" IS NULL)
);
ALTER TABLE "construction_site_work"."equipment_maintenance" ADD CONSTRAINT "equipment_maintenance_dates_check" CHECK (("end_date" IS NULL OR "end_date" >= "start_date") AND ("cost" IS NULL OR "cost" >= 0));

-- Equipment Usage sheets.
ALTER TABLE "construction_site_work"."equipment_usage_sheets" ADD CONSTRAINT "equipment_usage_sheets_figures_check" CHECK (
  ("usage_hours" IS NULL OR "usage_hours" >= 0)
  AND ("distance_km" IS NULL OR "distance_km" >= 0)
  AND ("trips" IS NULL OR "trips" >= 0)
  AND "idle_hours" >= 0
  AND "breakdown_hours" >= 0
  AND coalesce("usage_hours", 0) + "idle_hours" + "breakdown_hours" <= 24
  AND ("closing_reading" IS NULL OR "opening_reading" IS NULL OR "closing_reading" >= "opening_reading")
  AND ("fuel_qty" IS NULL OR "fuel_qty" >= 0)
  AND ("approx_work_qty" IS NULL OR ("approx_work_qty" > 0 AND "approx_work_unit_id" IS NOT NULL))
);
ALTER TABLE "construction_site_work"."equipment_usage_sheets" ADD CONSTRAINT "equipment_usage_sheets_hire_check" CHECK (
  ("ownership" = 'rented' OR ("unit_rate" IS NULL AND "billable_qty" IS NULL AND "hire_cost" IS NULL))
  AND ("unit_rate" IS NULL OR "unit_rate" >= 0)
  AND ("billable_qty" IS NULL OR "billable_qty" >= 0)
  AND ("hire_cost" IS NULL OR "hire_cost" >= 0)
);
ALTER TABLE "construction_site_work"."equipment_usage_sheets" ADD CONSTRAINT "equipment_usage_sheets_rejection_check" CHECK ("approval_status" <> 'rejected' OR "rejection_reason" IS NOT NULL);
ALTER TABLE "construction_site_work"."equipment_time_shifts" ADD CONSTRAINT "equipment_time_shifts_time_check" CHECK (
  "start_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  AND "end_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  AND "minutes" BETWEEN 1 AND 1440
);
ALTER TABLE "construction_site_work"."equipment_usage_materials" ADD CONSTRAINT "equipment_usage_materials_quantity_check" CHECK ("quantity" > 0);

-- Site Diary and Hindrances.
ALTER TABLE "construction_site_work"."site_diaries" ADD CONSTRAINT "site_diaries_rainfall_check" CHECK ("rainfall_mm" IS NULL OR "rainfall_mm" >= 0);
ALTER TABLE "construction_site_work"."site_diary_visitors" ADD CONSTRAINT "site_diary_visitors_time_check" CHECK (
  ("time_in" IS NULL OR "time_in" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
  AND ("time_out" IS NULL OR "time_out" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
);
ALTER TABLE "construction_site_work"."hindrances" ADD CONSTRAINT "hindrances_figures_check" CHECK (
  ("end_date" IS NULL OR "end_date" >= "start_date")
  AND ("hours_lost" IS NULL OR "hours_lost" >= 0)
  AND ("responsible_party" <> 'contractor' OR "contractor_id" IS NOT NULL)
);
